using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace Prometheus {
 public sealed class Sam2Prompt090 {public int frame;public double x,y;public bool positive=true;public int object_id=1;}
 public sealed class Sam2Layer0104 {public int object_id=1;public bool enabled=true,overlay_visible,inverted;public double feather;public string blend="add";}
 public sealed class Sam2MaskTrack090 {public bool enabled=true,composite_inverted,static_preview,stale;public int anchor_frame;public string directory;public int frames,width,height,fps=60;public double source_in,duration,speed=1;public string target="opacity";public List<Sam2Prompt090> prompts=new List<Sam2Prompt090>();public List<Sam2Layer0104> layers=new List<Sam2Layer0104>();}
 public static class Sam2MaskStore090 {
  public const string Namespace="prometheus.mask.sam2.v1";
  public static Sam2MaskTrack090 Get(Clip clip){var item=clip.extensions==null?null:clip.extensions.FirstOrDefault(x=>x.@namespace==Namespace);return item==null?null:Store.Json().Deserialize<Sam2MaskTrack090>(Store.Json().Serialize(item.payload));}
  public static void Put(Clip clip,Sam2MaskTrack090 track){if(clip.extensions==null)clip.extensions=new List<Extension>();clip.extensions.RemoveAll(x=>x.@namespace==Namespace);if(track!=null)clip.extensions.Add(new Extension{@namespace=Namespace,version="1",payload=(Dictionary<string,object>)Store.Fields(track)});}
  public static List<Sam2Layer0104> Layers(Sam2MaskTrack090 data){return data==null?new List<Sam2Layer0104>():data.layers!=null&&data.layers.Count>0?data.layers:new List<Sam2Layer0104>{new Sam2Layer0104()};}
  public static string LayerDirectory(Sam2MaskTrack090 data,Sam2Layer0104 layer){return data.layers==null||data.layers.Count==0?data.directory:Path.Combine(data.directory,"object-"+layer.object_id);}
  public static bool Active(Clip clip){var data=Get(clip);return data!=null&&data.enabled&&Layers(data).Any(layer=>layer.enabled);}
  public static int FirstFrame(Clip clip,Sam2MaskTrack090 data){return data.static_preview?0:(int)Math.Round((clip.source_in.Seconds-data.source_in)/Math.Max(0.001,data.speed)*data.fps);}
  public static bool Ready(Clip clip){var data=Get(clip);if(data==null||data.stale||data.frames<1||Math.Abs(data.speed-clip.speed.Seconds)>0.00001||String.IsNullOrWhiteSpace(data.directory))return false;int first=FirstFrame(clip,data),last=data.static_preview?0:first+Math.Max(1,(int)Math.Ceiling(clip.duration.Seconds*data.fps))-1;return first>=0&&last<data.frames&&Layers(data).Where(layer=>layer.enabled).All(layer=>File.Exists(Path.Combine(LayerDirectory(data,layer),first.ToString("D6")+".png"))&&File.Exists(Path.Combine(LayerDirectory(data,layer),last.ToString("D6")+".png")));}
  public static string DirectoryFor(string projectFile,string projectId,string clipId){return projectFile==null?Path.Combine(ProjectStorage.RecoveryDirectory,"SAM2",projectId,clipId):Path.Combine(ProjectStorage.DataDirectory(projectFile),"mascaras","sam2",clipId);}
  public static void Reconnect(Project project,string projectFile){foreach(var clip in project.sequences.SelectMany(s=>s.clips)){var data=Get(clip);if(data==null)continue;string candidate=DirectoryFor(projectFile,project.id,clip.id);if(File.Exists(Path.Combine(candidate,"000000.png"))){data.directory=candidate;Put(clip,data);}}}
  public static void Materialize(Project project,string destinationFile){foreach(var clip in project.sequences.SelectMany(s=>s.clips)){var data=Get(clip);if(data==null||String.IsNullOrWhiteSpace(data.directory))continue;string target=DirectoryFor(destinationFile,project.id,clip.id);if(!File.Exists(Path.Combine(data.directory,"000000.png")))continue;if(!String.Equals(Path.GetFullPath(data.directory),Path.GetFullPath(target),StringComparison.OrdinalIgnoreCase)){Directory.CreateDirectory(target);foreach(string source in Directory.GetFiles(data.directory,"*.png",SearchOption.AllDirectories)){string relative=source.Substring(data.directory.Length).TrimStart(Path.DirectorySeparatorChar);string destination=Path.Combine(target,relative);Directory.CreateDirectory(Path.GetDirectoryName(destination));File.Copy(source,destination,true);}}data.directory=target;Put(clip,data);}}
  public static void Validate(Clip clip){var data=Get(clip);if(data==null)return;if(data.frames<0||data.frames>360000||data.width<0||data.height<0||data.fps!=60||data.anchor_frame<0||data.prompts==null||data.prompts.Count>1000||String.IsNullOrWhiteSpace(data.target)||data.target!="opacity"&&data.target!="unassigned"&&!data.target.StartsWith("effect:",StringComparison.Ordinal))throw new Exception("Datos de máscara SAM2 inválidos");foreach(var point in data.prompts)if(point==null||point.frame<0||(!data.static_preview&&point.frame>=Math.Max(1,data.frames))||point.object_id<1||point.object_id>64||point.x<0||point.x>1||point.y<0||point.y>1||Double.IsNaN(point.x)||Double.IsNaN(point.y))throw new Exception("Corrección SAM2 inválida");if(data.layers!=null){if(data.layers.Count>64||data.layers.Any(layer=>layer==null||layer.object_id<1||layer.object_id>64||layer.feather<0||layer.feather>0.2||layer.blend!="add"&&layer.blend!="subtract"&&layer.blend!="intersect"))throw new Exception("Capa de máscara SAM2 inválida");}}
 }
}
